// --- Naive QuickSort ---
void naiveQuickSort(std::vector<double>& a, int lo, int hi) {
    if (lo >= hi) return;
    double pivot = a[lo];
    int i = lo, j = hi;
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            std::swap(a[i], a[j]);
            i++; j--;
        }
    }
    if (lo < j)   naiveQuickSort(a, lo, j);
    if (i < hi)   naiveQuickSort(a, i, hi);
}

// --- Reasonable QuickSort with optimizations ---
void insertionSort(std::vector<double>& a, int lo, int hi) {
    for (int i = lo + 1; i <= hi; i++) {
        double key = a[i];
        int j = i - 1;
        while (j >= lo && a[j] > key) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }
}

double medianOf3(std::vector<double>& a, int lo, int hi) {
    int mid = lo + (hi - lo) / 2;
    if (a[lo] > a[mid]) std::swap(a[lo], a[mid]);
    if (a[lo] > a[hi]) std::swap(a[lo], a[hi]);
    if (a[mid] > a[hi]) std::swap(a[mid], a[hi]);
    std::swap(a[mid], a[hi - 1]);
    return a[hi - 1];
}

